import { readFileSync, readdirSync } from 'fs';

export const readFileSafely = (file: string) => {
  try {
    return readFileSync(file, 'utf8');
  } catch (err) {
    return '';
  }
};

export const readDirSafely = (dir: string) => {
  try {
    return readdirSync(dir);
  } catch (err) {
    return [];
  }
};

export const fileExists = (file: string) => !!readFileSafely(file);
